import{_ as n,c as t,o as d,ah as r}from"./chunks/framework.CZ6YNuB6.js";const g=JSON.parse('{"title":"33. Frontend","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-c-entwicklungs-systemdokumentation/33-frontend.md","filePath":"manual/teil-c-entwicklungs-systemdokumentation/33-frontend.md"}'),i={name:"manual/teil-c-entwicklungs-systemdokumentation/33-frontend.md"};function o(s,e,c,a,l,u){return d(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_33-frontend" tabindex="-1">33. Frontend <a class="header-anchor" href="#_33-frontend" aria-label="Permalink to &quot;33. Frontend&quot;">​</a></h1><p>Dieses Kapitel beschreibt die Weboberfläche von innen: wie sie aufgebaut ist, wie sie Daten holt und hält, wie Karte und Diagramme entstehen und wie Sprache, Gestaltung und Einstellungen funktionieren. Wie Sie das Frontend lokal starten, beschreibt Abschnitt <a href="./30-entwicklungsumgebung.html#_30-3-frontend-starten">Frontend starten</a>. Alle Pfade sind relativ zu <code>frontend/</code>.</p><h2 id="_33-1-sveltekit-struktur-und-routen" tabindex="-1">33.1 SvelteKit-Struktur und Routen <a class="header-anchor" href="#_33-1-sveltekit-struktur-und-routen" aria-label="Permalink to &quot;33.1 SvelteKit-Struktur und Routen&quot;">​</a></h2><p>Das Frontend ist eine SvelteKit-Anwendung mit Svelte 5 und TypeScript. Es läuft mit <code>@sveltejs/adapter-node</code> als eigener Node-Prozess und rendert jede Seite beim ersten Aufruf auf dem Server vor. Zwei experimentelle Schalter sind eingeschaltet (<code>svelte.config.js</code>): <code>kit.experimental.remoteFunctions</code> für die Remote Functions, siehe Abschnitt <a href="#_33-2-zustandsverwaltung-kontexte-und-remote-functions">Zustandsverwaltung</a>, und <code>compilerOptions.experimental.async</code> für <code>await</code> in Komponenten.</p><p>Unter <code>src/routes/</code> liegt je Menüpunkt eine Route. Die Ansichten, die zu einem Projekt gehören, liegen unter <code>project/[projectId=integer]/</code>, die übrigen daneben:</p><table tabindex="0"><thead><tr><th>Route</th><th>Ansicht</th></tr></thead><tbody><tr><td><code>project/[projectId=integer]/dashboard/[[flagId]]</code></td><td>Dashboard</td></tr><tr><td><code>project/[projectId=integer]/map</code></td><td>Karte</td></tr><tr><td><code>project/[projectId=integer]/fault-simulation</code>, <code>…/post-compaction</code>, <code>…/valuation</code></td><td>Störungsanalyse, Nachverdichtung, Wertermittlung</td></tr><tr><td><code>project/[projectId=integer]/conduit</code>, <code>…/trench/[[flagId]]</code>, <code>…/pipe-branch</code>, <code>…/house-connections</code></td><td>Rohrverwaltung, Rohrzuordnung, Rohrverzweigung, Mikrorohre</td></tr><tr><td><code>project/[projectId=integer]/network-schema</code></td><td>Netzschema, mit <code>node/[nodeId]</code> für das Unternetz eines Netzknotens</td></tr><tr><td><code>project/[projectId=integer]/address</code></td><td>Adressen, mit <code>[uuid]</code> und <code>[uuid]/unit/[unitUuid]</code></td></tr><tr><td><code>pipeline-records</code>, <code>trace/[entryType=traceEntryType]/[uuid]</code></td><td>Leitungsauskunft, Faserweg</td></tr><tr><td><code>settings</code>, <code>admin/logs</code></td><td>Einstellungen, Logs</td></tr><tr><td><code>login</code>, <code>no-access</code></td><td>Anmeldung, Hinweis für Konten ohne erlaubte Seite</td></tr></tbody></table><p>Zwei <strong>Parameterprüfungen</strong> in <code>src/params/</code> lassen nur passende Pfade zu: <code>integer</code> nur Ziffern als Projektnummer, <code>traceEntryType</code> nur die Einstiegspunkte des Faserwegs (<code>fiber</code>, <code>cable</code>, <code>node</code>, <code>address</code>, <code>residential-unit</code>). Ein anderer Wert ergibt 404, ebenso ein Pfad ohne Projekt wie <code>/map</code>. <code>project/[projectId=integer]/+layout.ts</code> prüft die Nummer gegen die Projekte des Kontos und antwortet mit 404, wenn das Konto das Projekt nicht sieht; <code>/project/&lt;Nummer&gt;</code> allein leitet auf dessen Karte weiter. Die Route-IDs, mit denen der übrige Code arbeitet, sammelt <code>src/lib/config/routes.ts</code>. Neben den Ansichten gibt es einen einzigen eigenen Server-Endpunkt, <code>conduit/download/+server.ts</code>, der die Excel-Vorlage des Rohrimports vom Backend durchreicht.</p><p><strong>Die Adresse als Zustand.</strong> Welche Seite offen ist und was sie gerade zeigt, steht in der Adresse, nicht in einem Store:</p><ul><li><strong>Pfad</strong> – das Projekt und die Detailseiten (<code>/project/2/address/&lt;uuid&gt;</code>).</li><li><strong>Abfrageparameter</strong> – das in der Info-Box geöffnete Objekt (<code>feature=trench:&lt;uuid&gt;</code>), der Reiter (<code>tab</code>), Suchbegriff und Seite (<code>search</code>, <code>page</code>, <code>page_size</code>). Die Namen sind reserviert, keine Ansicht verwendet sie für etwas anderes; die Hilfsfunktionen dazu stehen in <code>src/lib/utils/urlState.ts</code> (<code>setQuery</code>, <code>openFeature</code>, <code>closeFeature</code>).</li><li><strong>Fragment</strong> – der Kartenausschnitt als <code>#map=&lt;Zoom&gt;/&lt;x&gt;/&lt;y&gt;</code> in EPSG:3857, siehe Abschnitt <a href="#_33-7-benutzereinstellungen-und-deren-speicherung">Benutzereinstellungen und deren Speicherung</a>.</li></ul><p>Das Öffnen eines Objekts legt einen Eintrag im Verlauf des Browsers an; Reiter, Filter, Seiten und Bewegungen der Karte ersetzen den aktuellen. „Zurück“ schließt deshalb die Info-Box in einem Schritt, statt jeden Reiterwechsel einzeln zurückzunehmen. Das Projekt einer Seite liefert <code>routeProjectId()</code> aus <code>src/lib/context/project.ts</code>; Komponenten, die je Projekt eigenen Zustand halten, etwa eine OpenLayers-Karte, reagieren mit <code>onProjectChange()</code> auf einen Wechsel.</p><p><strong>Daten.</strong> Die Ansichten holen und speichern ihre Daten über Remote Functions, siehe Abschnitt <a href="#_33-2-zustandsverwaltung-kontexte-und-remote-functions">Zustandsverwaltung</a>. Lade-Funktionen gibt es nur noch an wenigen Stellen: Die Wurzel <code>+layout.server.ts</code> lädt für jede Seite die Projekte, die Kennzeichen, die Konfiguration vom Endpunkt <code>config/</code> des Backends (Koordinatenbezugssystem und seine Definition für proj4), die Version der Anwendung und das zuletzt besuchte Projekt; dazu kommen die Seiten des Netzschemas und <code>admin/logs</code>. Die Wurzel liest nichts aus der Adresse und läuft deshalb beim Navigieren nicht erneut, sondern nur, wenn <code>app:reference-data</code> ungültig wird.</p><p><strong>Wie das Frontend das Backend aufruft.</strong> Es gibt keinen generierten Client; der Code ruft <code>fetch</code> direkt auf, auf den beiden Wegen aus Abschnitt <a href="./29-architekturueberblick.html#_29-1-komponenten-und-weg-einer-anfrage">Komponenten und Weg einer Anfrage</a>. Auf dem Server reicht <code>getAuthHeaders()</code> (<code>src/lib/utils/getAuthHeaders.ts</code>) das Zugangstoken <code>api-access-token</code> aus der Anfrage des Browsers als <code>Cookie</code>-Header weiter; im Browser schickt <code>credentials: &#39;include&#39;</code> die Anmelde-Cookies mit.</p><p>Die Typen der Antworten kommen aus <code>src/lib/types/api.d.ts</code>, die openapi-typescript aus dem Schema des Backends erzeugt, siehe Abschnitt <a href="./32-rest-api.html#_32-7-openapi-schema-und-typgenerierung">OpenAPI-Schema und Typgenerierung</a>. <code>src/lib/types/index.ts</code> gibt ihnen kürzere Namen. Die Typen prüfen nur zur Entwicklungszeit; eine Prüfung der Antworten zur Laufzeit findet nicht statt.</p><p>Unbehandelte Fehler im Browser schickt <code>src/hooks.client.ts</code> an <code>logs/frontend/</code> des Backends; sie erscheinen in den Protokollen mit der Quelle „Frontend“, siehe Abschnitt <a href="./../teil-b-betrieb-admin-qgis/28-betrieb-der-instanz.html#_28-5-protokolle-auswerten">Protokolle auswerten</a>.</p><p><code>src/service-worker.ts</code> und <code>static/manifest.webmanifest</code> machen die Anwendung im Browser installierbar. Der Service Worker speichert nichts zwischen; ohne Verbindung zum Server funktioniert die Anwendung nicht.</p><h2 id="_33-2-zustandsverwaltung-kontexte-und-remote-functions" tabindex="-1">33.2 Zustandsverwaltung, Kontexte und Remote Functions <a class="header-anchor" href="#_33-2-zustandsverwaltung-kontexte-und-remote-functions" aria-label="Permalink to &quot;33.2 Zustandsverwaltung, Kontexte und Remote Functions&quot;">​</a></h2><p>Die Komponenten nutzen durchgehend die <strong>Runes</strong> von Svelte 5 (<code>$state</code>, <code>$derived</code>, <code>$effect</code>, <code>$props</code>); die Schreibweise von Svelte 4 (<code>export let</code>, <code>$:</code>) kommt nicht mehr vor. Für Zustand, der über eine Komponente hinausgeht, gibt es drei Mittel nebeneinander:</p><ul><li><strong>Zustandsklassen</strong> – Klassen mit <code>$state</code>-Feldern, die den Zustand und die Logik einer Ansicht bündeln. Was mehrere Ansichten nutzen, liegt in <code>src/lib/classes/*.svelte.ts</code>: <code>MapState</code> und die <code>Map…Manager</code> der Karte, <code>NetworkSchemaState</code> mit seinen Managern, <code>NodeStructureManager</code>, <code>FiberSpliceManager</code>, <code>DragDropManager</code> für die Netzknotenstruktur, <code>AddressState</code> und andere. Klassen einer einzelnen Ansicht liegen neben ihrer Route, etwa <code>TrenchAssignmentState</code>, <code>PipeBranchState</code>, <code>FaultSimulationState</code> oder <code>ValuationState</code>.</li><li><strong>Kontexte</strong> – eine Ansicht erzeugt ihre Zustandsklassen einmal und reicht sie an ihre Komponenten weiter, meist über typisierte Kontexte aus <code>createContext</code> von Svelte (<code>src/lib/context/networkSchemaContext.ts</code>, <code>src/lib/context/project.ts</code> und die Klassen der Ansichten). Zeichenketten als Schlüssel nutzen noch die Karte (<code>&#39;mapManagers&#39;</code>) und die Auswahllisten (<code>&#39;attributeOptions&#39;</code>).</li><li><strong>Stores</strong> in <code>src/lib/stores/</code> – die Stores von Svelte nur noch für persönliche Vorlieben und Meldungen: die Einstellungen in <code>store.ts</code> und <code>sidebarPreferences.ts</code>, siehe Abschnitt <a href="#_33-7-benutzereinstellungen-und-deren-speicherung">Benutzereinstellungen und deren Speicherung</a>, und <code>toaster.ts</code>. Projekt, geöffnetes Objekt und Reiter stehen in der Adresse, siehe Abschnitt <a href="#_33-1-sveltekit-struktur-und-routen">SvelteKit-Struktur und Routen</a>; das angemeldete Konto mit seinen Rechten liefert die Wurzel-Lade-Funktion in <code>page.data.user</code>.</li></ul><p><strong>Remote Functions</strong> von SvelteKit sind der Weg, auf dem alle Ansichten ihre Fachdaten lesen und schreiben. Sie liegen in <code>src/lib/remote/&lt;Bereich&gt;/</code> – <code>address</code>, <code>conduit</code>, <code>map</code>, <code>network-schema</code>, <code>trace</code> usw.:</p><ul><li><code>*.remote.ts</code> enthält die Funktionen selbst: <code>query</code> zum Lesen, <code>command</code> zum Schreiben, <code>form</code> für Anmeldung, Abmeldung und den Excel-Import der Rohre. Ihre Eingaben prüft valibot.</li><li>Gleichnamige Dateien ohne <code>.remote</code> enthalten reine Hilfsfunktionen, etwa die Umformung der Antworten, mit eigenen Tests.</li><li><code>shared/</code> enthält, was alle brauchen: <code>djangoHeaders()</code> in <code>remote-auth.ts</code>, das die Anmeldung über <code>getRequestEvent()</code> aus der laufenden Anfrage holt, und <code>failFromResponse()</code> in <code>backend-error.ts</code>, das eine Fehlerantwort des Backends in einen Fehler mit Status und Meldung umsetzt.</li></ul><p>Die Funktionen laufen auf dem Server und rufen das Backend über <code>API_URL</code> auf. Komponenten rufen eine <code>query</code> direkt auf und stellen sie in <code>QueryBoundary.svelte</code> dar, das bis zur Antwort einen Platzhalter und bei einem Fehler die Meldung mit der Schaltfläche „Erneut versuchen“ zeigt.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Zwei Regeln gelten für jede neue Remote Function. <code>djangoHeaders()</code> muss vor dem ersten <code>await</code> stehen, weil <code>getRequestEvent()</code> danach keine Anfrage mehr kennt. Und Fehler müssen als <code>HttpError</code> von SvelteKit geworfen werden (<code>error()</code> oder <code>failFromResponse()</code>): Ein gewöhnliches <code>Error</code> erreicht den Browser nur als „Internal Error“, und die Meldung des Backends geht verloren.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Remote Functions sind in SvelteKit zum Stand des Handbuchs experimentell. Ihre Schnittstelle kann sich mit einer neuen Version von SvelteKit ändern, und weil die ganze Oberfläche auf ihnen aufbaut, betrifft eine solche Änderung jede Ansicht. Prüfen Sie nach einer Aktualisierung von <code>@sveltejs/kit</code> die Ansichten durchgehend, nicht nur stichprobenhaft.</p></div><h2 id="_33-3-kartenintegration-mit-openlayers" tabindex="-1">33.3 Kartenintegration mit OpenLayers <a class="header-anchor" href="#_33-3-kartenintegration-mit-openlayers" aria-label="Permalink to &quot;33.3 Kartenintegration mit OpenLayers&quot;">​</a></h2><p>Die Karte ist OpenLayers 10, aufgebaut in <code>src/lib/components/Map.svelte</code>; die Logik für Auswahl, Info-Box, Messen und Hervorheben liegt in den Klassen <code>MapState</code>, <code>MapInteractionManager</code>, <code>MapSelectionManager</code>, <code>MapPopupManager</code> und <code>MapMeasureManager</code>. Der Faserweg hat eine eigene Karte (<code>src/routes/trace/components/TraceMap.svelte</code>). Was in der Karte zu sehen ist, stammt aus drei Quellen, siehe Abschnitt <a href="./29-architekturueberblick.html#_29-1-komponenten-und-weg-einer-anfrage">Komponenten und Weg einer Anfrage</a>.</p><p><strong>Hintergrundkarte.</strong> <code>ol-mapbox-style</code> wendet den Stil <code>${PUBLIC_TILE_SERVER_URL}/styles/light/style.json</code> bzw. <code>…/dark/…</code> auf die Karte an. Ist der Kachelserver nicht erreichbar oder die Variable leer, fällt die Karte auf Rasterkacheln von OpenStreetMap zurück und hält das im Store <code>tileServerAvailable</code> fest, siehe auch Abschnitt <a href="./../teil-b-betrieb-admin-qgis/28-betrieb-der-instanz.html#_28-6-kartenkacheln-bereitstellen-und-erneuern">Kartenkacheln bereitstellen und erneuern</a>.</p><p><strong>Netzobjekte.</strong> Trassen, Netzknoten, Adressen und Gebiete kommen als Vektorkacheln vom Backend (<code>src/lib/map/tileSources.ts</code>), siehe Abschnitt <a href="./32-rest-api.html#_32-6-vektor-tile-endpunkte">Vektor-Tile-Endpunkte</a>. Ihre Verarbeitung ist auf Geschwindigkeit ausgelegt:</p><ul><li>Eine Kachel wird nicht im Hauptthread entpackt, sondern in einem Pool von Web Workern (<code>workerPool.ts</code>, <code>mvtParserWorker.ts</code>), mit so vielen Workern, wie der Rechner Kerne hat, höchstens vier. <code>featureReconstructor.ts</code> baut aus dem Ergebnis die Objekte für OpenLayers.</li><li>Wechselt jemand die Seite, bricht <code>navigationCancellation.ts</code> alle laufenden Kachelanfragen ab; <code>tileLoadingManager.ts</code> hält dafür die <code>AbortController</code> der Anfragen.</li><li>Antwortet das Backend auf eine Kachel mit 401, erneuert die Kachel die Anmeldung über <code>ensureFreshSession()</code> und wiederholt die Anfrage einmal; viele Kacheln zugleich lösen dabei nur eine Erneuerung aus, siehe Abschnitt <a href="#_33-8-anmeldung-token-erneuerung-und-routenschutz-im-frontend">Anmeldung, Token-Erneuerung und Routenschutz im Frontend</a>.</li></ul><p>GeoJSON nutzt die Karte nur für Ebenen, die eine Ansicht selbst erzeugt: Suchtreffer, Faserweg, Störungsanalyse, Nachverdichtung, Auskunftsbereiche, Wertermittlung.</p><p><strong>WMS-Ebenen.</strong> <code>TileWMS</code> in <code>src/lib/map/layers.ts</code> lädt die Bilder über den WMS-Proxy des Backends in Kacheln von 512 Pixeln in EPSG:3857. Quellen und Layer liest <code>src/lib/utils/wmsApi.ts</code> aus der Schnittstelle; den kurzlebigen Token für die Kachelanfragen hält <code>wmsTokenHeartbeat.svelte.ts</code> frisch.</p><p><strong>Projektion.</strong> Die Karte zeigt Web Mercator. Geometrien, die das Backend im Koordinatenbezugssystem der Installation liefert – Suchtreffer, Auskunftsbereiche der Leitungsauskunft, Wertermittlung –, rechnet sie mit proj4 um; <code>src/lib/map/projectionUtils.ts</code> registriert dafür die Definition vom Endpunkt <code>config/</code>.</p><p><strong>Stile.</strong> Wie die Objekte aussehen, legt <code>src/lib/map/styles.ts</code> fest, mit den Vorgabefarben aus <code>defaultColors.ts</code>; die Einstellungen der Nutzenden aus Kapitel <a href="./../teil-a-anwenderhandbuch/17-einstellungen.html">Einstellungen</a> überschreiben sie.</p><h2 id="_33-4-diagramm-und-canvas-ansichten" tabindex="-1">33.4 Diagramm- und Canvas-Ansichten <a class="header-anchor" href="#_33-4-diagramm-und-canvas-ansichten" aria-label="Permalink to &quot;33.4 Diagramm- und Canvas-Ansichten&quot;">​</a></h2><p>Drei Ansichten zeichnen Knoten und Kanten mit <strong>Svelte Flow</strong> (<code>@xyflow/svelte</code>):</p><ul><li>das <strong>Netzschema</strong> (<code>src/routes/project/[projectId=integer]/network-schema</code>) mit eigenen Knoten und Kanten für Netzknoten und Kabel (<code>CableDiagramNode</code>, <code>CableDiagramEdge</code>, <code>DynamicEdgeLabel</code>) und das Unternetz eines Netzknotens (<code>…/node/[nodeId]</code>),</li><li>die <strong>Rohrverzweigung</strong> (<code>src/routes/project/[projectId=integer]/pipe-branch</code>) mit eigenen Knoten und Kanten für Rohre und Mikrorohre und einer Lasso-Auswahl, die auf ein eigenes Canvas zeichnet (<code>PipeBranchLasso.svelte</code>),</li><li>das <strong>Grabenprofil</strong> einer Trasse in der Karte (<code>…/map/components/trench-profile/</code>).</li></ul><p>Die Lage der Knoten im Netzschema speichert das Backend (<code>canvas_x</code>, <code>canvas_y</code> am Netzknoten, <code>diagram_path</code> am Kabel, siehe Abschnitt <a href="./31-datenmodell-des-backends.html#_31-4-kabel-faser-spleiß">Kabel, Faser, Spleiß</a>). Die erste Lage eines neuen Netzknotens setzt ein Trigger der Datenbank, siehe Abschnitt <a href="./31-datenmodell-des-backends.html#_31-5-netzknotenstruktur-container-slots-und-komponenten">Netzknotenstruktur</a>; das Frontend rechnet keine Lagen aus. Der Ausschnitt, den jemand gerade betrachtet, steht im Browser (<code>networkSchemaViewport</code>).</p><p>Die <strong>Netzknotenstruktur</strong> – Steckplätze, Komponenten, Ports, Spleiße – ist dagegen kein Svelte-Flow-Diagramm, sondern gewöhnliches HTML; das Ziehen und Ablegen übernimmt <code>DragDropManager</code>.</p><p>Die <strong>Diagramme</strong> des Dashboards zeichnet Chart.js, gekapselt in <code>src/lib/components/Chart.svelte</code>, <code>DonutChart.svelte</code> und <code>StackedBarChart.svelte</code>. Die PDF-Dokumente der Nachverdichtung und der Adressen entstehen mit jsPDF im Browser.</p><h2 id="_33-5-internationalisierung-mit-paraglide" tabindex="-1">33.5 Internationalisierung mit Paraglide <a class="header-anchor" href="#_33-5-internationalisierung-mit-paraglide" aria-label="Permalink to &quot;33.5 Internationalisierung mit Paraglide&quot;">​</a></h2><p>Die Texte der Oberfläche übersetzt Paraglide 2. Die Einstellungen stehen in <code>project.inlang/settings.json</code>: Ausgangssprache Deutsch (<code>baseLocale: &quot;de&quot;</code>), Sprachen <code>de</code> und <code>en</code>, die Texte in <code>messages/de.json</code> und <code>messages/en.json</code>. Das Vite-Plugin übersetzt sie beim Bauen in Funktionen in <code>src/lib/paraglide/</code>, die nicht im Repository liegen; im Code steht ein Text als Aufruf, etwa <code>m.nav_dashboard()</code>.</p><p>Die Sprache bestimmt Paraglide über die Strategie <code>[&#39;localStorage&#39;, &#39;baseLocale&#39;]</code> (<code>vite.config.ts</code> und das Skript <code>paraglide</code> in <code>package.json</code>): zuerst den Schlüssel <code>PARAGLIDE_LOCALE</code> im <code>localStorage</code> des Browsers, sonst Deutsch. Daraus folgt:</p><ul><li>Der Server kennt <code>localStorage</code> nicht und rendert jede Seite <strong>auf Deutsch</strong>. Wer Englisch gewählt hat, sieht beim Laden kurz die deutsche Fassung, bis der Browser übernimmt.</li><li>Texte, die eine Lade- oder Remote Function auf dem Server mit Paraglide erzeugt, bleiben deutsch. Die meisten Fehlermeldungen der Server-Seite stehen ohnehin fest auf Englisch im Code oder kommen vom Backend.</li><li>Die Sprache ist eine Einstellung des Browsers, nicht des Kontos, siehe Abschnitt <a href="#_33-7-benutzereinstellungen-und-deren-speicherung">Benutzereinstellungen und deren Speicherung</a>.</li></ul><p>Das Backend übersetzt seine eigenen Texte – den Administrationsbereich, Meldungen der Schnittstelle – unabhängig davon mit gettext von Django, siehe Abschnitt <a href="./36-erweitern-und-mitwirken.html#_36-3-eine-weitere-sprache-erganzen">Eine weitere Sprache ergänzen</a>.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Der Kommentar in <code>src/lib/utils/userSettingsSync.ts</code>, die Sprache liege in einem eigenen Cookie, stimmt zum Stand des Handbuchs nicht; sie liegt im <code>localStorage</code>.</p></div><h2 id="_33-6-designsystem-theming-und-komponenten" tabindex="-1">33.6 Designsystem, Theming und Komponenten <a class="header-anchor" href="#_33-6-designsystem-theming-und-komponenten" aria-label="Permalink to &quot;33.6 Designsystem, Theming und Komponenten&quot;">​</a></h2><p>Gestaltet ist die Oberfläche mit <strong>Tailwind CSS 4</strong> und <strong>Skeleton 5</strong> (<code>@skeletonlabs/skeleton</code>, <code>@skeletonlabs/skeleton-svelte</code>). Es gibt keine <code>tailwind.config</code>; Tailwind, das Formular-Plugin, Skeleton und dessen Theme <code>legacy</code> werden in <code>src/app.css</code> eingebunden, wo auch die Anpassungen für Svelte Flow und die Meldungen stehen. Die Symbole kommen aus <code>@tabler/icons-svelte</code>.</p><ul><li><strong>Theme</strong> – <code>+layout.svelte</code> schreibt das Theme aus dem Store <code>theme</code> in das Attribut <code>data-theme</code> von <code>&lt;html&gt;</code>.</li><li><strong>Hell und dunkel</strong> – die Tailwind-Variante <code>dark</code> gilt unter <code>[data-mode=&quot;dark&quot;]</code> (<code>@custom-variant dark</code> in <code>app.css</code>). <code>src/lib/components/LightSwitch.svelte</code> setzt das Attribut, speichert den Modus im Schlüssel <code>mode</code> des <code>localStorage</code> und setzt außerdem den Store <code>lightSwitchMode</code>. Gelesen wird nur <code>mode</code>. <code>lightSwitchMode</code> abonniert keine Komponente, und ein <code>persisted()</code>-Store schreibt erst in den <code>localStorage</code>, sobald er abonniert ist – der Schlüssel <code>lightSwitchMode</code> entsteht deshalb nie. Die Hintergrundkarte hat ihren eigenen Hell-Dunkel-Schalter (<code>basemapTheme</code>).</li></ul><p>Gemeinsame Komponenten liegen flach in <code>src/lib/components/</code>: Karte, Info-Box (<code>Drawer</code>), Navigationsleiste (<code>SideBar</code>, unterhalb von 768 Pixeln <code>MobileNav</code>), Kopfzeile (<code>AppBar</code>), Auswahllisten, Diagramme, Suchfelder. Was nur eine Ansicht braucht, liegt neben ihrer Route. Von Skeleton kommen vor allem die Bausteine für Dialoge, Reiter, Akkordeons, Menüs, Auswahllisten, Schalter, Schieberegler, Seitenwechsel, Datei-Uploads und Meldungen.</p><h2 id="_33-7-benutzereinstellungen-und-deren-speicherung" tabindex="-1">33.7 Benutzereinstellungen und deren Speicherung <a class="header-anchor" href="#_33-7-benutzereinstellungen-und-deren-speicherung" aria-label="Permalink to &quot;33.7 Benutzereinstellungen und deren Speicherung&quot;">​</a></h2><p>Die Einstellungen der Oberfläche liegen im <code>localStorage</code> des Browsers. <code>persisted()</code> in <code>src/lib/stores/persisted.ts</code> ist ein Store von Svelte, der seinen Wert beim ersten Abonnieren aus dem <code>localStorage</code> liest und jede Änderung dorthin zurückschreibt, als JSON unter einem festen Schlüssel. So sind in <code>src/lib/stores/store.ts</code> rund 35 Einstellungen angelegt: Sichtbarkeit und Transparenz der Layer, Trassenfarben und Stile der Netzknotentypen, Adressen und Gebiete, Routing-Toleranz, Breite der Info-Box, Anzeigeoptionen des Netzschemas, Lage und Größe verschiebbarer Fenster (<code>floatingPanelRects</code>) und mehr. <code>sidebarPreferences.ts</code> hält die ausgeblendeten Menüpunkte und eingeklappten Gruppen der Navigationsleiste. Zwei Ansichtszustände – das gewählte Rohr (<code>selectedConduit</code>) und ob die Legende der Karte aufgeklappt ist (<code>layerTreeExpanded</code>) – legt <code>session()</code> aus <code>session.ts</code> stattdessen im <code>sessionStorage</code> ab; sie gelten nur, solange der Tab offen ist.</p><p>Der <code>localStorage</code> gehört zur Adresse der Weboberfläche im Browser, nicht zum Konto. Melden sich zwei Personen nacheinander im selben Browser an, teilen sie die Einstellungen.</p><p><strong>Kartenausschnitt.</strong> Den Ausschnitt einer Karte speichert kein Store. Die Karten der Ansichten Karte, Rohrzuordnung, Mikrorohre, Störungsanalyse und Wertermittlung schreiben ihn nach jeder Bewegung in das Fragment der Adresse (<code>#map=&lt;Zoom&gt;/&lt;x&gt;/&lt;y&gt;</code>, <code>src/lib/map/viewHash.ts</code>) und zusätzlich je Projekt in den <code>localStorage</code> unter <code>mapView:&lt;Projektnummer&gt;</code> (<code>src/lib/map/storedView.ts</code>). Beim Öffnen gilt das Fragment, dann der gespeicherte Ausschnitt des Projekts, dann die Ausdehnung seiner Trassen; ein leeres Projekt öffnet mit der Voreinstellung. Weil das Fragment nie zum Server geht, rendert dieser die Karte ohne Ausschnitt; erst der Browser setzt ihn.</p><p><strong>Zuletzt besuchtes Projekt.</strong> Das Cookie <code>last-project</code> (<code>src/lib/utils/rememberedProject.ts</code>) merkt sich das Projekt, das zuletzt in der Adresse stand. Es wählt nur, wohin die Anmeldung und <code>/</code> führen und welches Projekt projektübergreifende Seiten wie die Leitungsauskunft vorschlagen; was eine Projektadresse zeigt, entscheidet allein ihr Pfad. Es überdauert die Abmeldung, und jeder Zugriff prüft es gegen die Projekte des Kontos.</p><p><strong>Im Konto speichern.</strong> <code>src/lib/utils/userSettingsSync.ts</code> überträgt die Einstellungen auf Wunsch ins Backend, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/17-einstellungen.html#_17-2-einstellungen-im-konto-speichern-und-wieder-laden">Einstellungen im Konto speichern und wieder laden</a>:</p><ul><li><code>saveUserSettings()</code> liest die Schlüssel aus der Liste <code>SYNCED_SETTINGS_KEYS</code> aus dem <code>localStorage</code> und übergibt sie der Remote Function <code>saveSettings</code>, die sie mit <code>PUT user-settings/</code> an das Backend schickt; es legt sie als JSON in <code>user_settings</code> ab.</li><li><code>loadUserSettings()</code> holt sie über <code>getSavedSettings</code> mit <code>GET user-settings/</code> und schreibt sie zurück in den <code>localStorage</code>.</li></ul><p>Übertragen wird nur, was in <code>SYNCED_SETTINGS_KEYS</code> steht. Kartenausschnitte, Sprache, der Schlüssel <code>mode</code> und die Lage der Fenster, die vom Bildschirm abhängt, gehören nicht dazu. Die Liste enthält zwar <code>lightSwitchMode</code>, aber weil die Oberfläche den Modus aus <code>mode</code> liest, folgt der Hell- oder Dunkelmodus dem Konto nicht. Eine neue Einstellung, die sich im Konto speichern lassen soll, braucht deshalb zwei Einträge: den <code>persisted()</code>-Store und den Schlüssel in der Liste. Das Speichern und Laden geschieht nur auf Knopfdruck; ein automatischer Abgleich zwischen Geräten findet nicht statt. Nach dem Laden lädt die Einstellungsseite die ganze Seite neu (<code>location.reload()</code>), weil die bereits abonnierten Stores den geänderten <code>localStorage</code> nicht von selbst lesen.</p><h2 id="_33-8-anmeldung-token-erneuerung-und-routenschutz-im-frontend" tabindex="-1">33.8 Anmeldung, Token-Erneuerung und Routenschutz im Frontend <a class="header-anchor" href="#_33-8-anmeldung-token-erneuerung-und-routenschutz-im-frontend" aria-label="Permalink to &quot;33.8 Anmeldung, Token-Erneuerung und Routenschutz im Frontend&quot;">​</a></h2><p>Die Anmeldung der Weboberfläche läuft über den Server des Frontends. Die Remote Function <code>login</code> (<code>src/lib/remote/auth/login.remote.ts</code>, ein <code>form</code>) schickt Benutzername und Passwort an <code>auth/login/</code> des Backends, übernimmt die Cookies aus dessen Antwort und setzt sie für die eigene Antwort an den Browser. Danach leitet sie auf <code>redirectTo</code> weiter, sofern das ein Pfad derselben Anwendung ist, sonst auf die <strong>Startseite</strong> des Kontos. <code>logout</code> meldet beim Backend ab und löscht die Cookies auch dann, wenn das Backend nicht antwortet.</p><p>Die Startseite bestimmt <code>src/lib/server/landing.ts</code>: die Karte des zuletzt besuchten Projekts (Cookie <code>last-project</code>), sonst des ersten Projekts des Kontos, ohne Projekt die Einstellungen. Verbieten die Routenrechte diese Seite, ist es die erste erlaubte in der Reihenfolge der Navigationsleiste, und ist keine erlaubt, <code>/no-access</code> mit dem Hinweis, sich an die Administration zu wenden. Eine feste Projektnummer gibt es dabei nicht.</p><p>Bei jeder Anfrage an den Server des Frontends laufen zwei Hooks nacheinander (<code>src/hooks.server.ts</code>): Paraglide und <code>handleAuth</code>. <code>handleAuth</code> ist die einzige Prüfung der Anmeldung; Lade-Funktionen prüfen nicht noch einmal. Der Hook</p><ol><li>ermittelt Konto und Rechte über <code>resolveSession()</code> (<code>src/lib/server/session.ts</code>): <code>auth/user/</code> und <code>auth/permissions/</code> beim Backend, beide gleichzeitig; bei 401 oder 403 erneuert er die Tokens einmal über <code>auth/token/refresh/</code> und fragt erneut,</li><li>lässt Aufrufe von Remote Functions durch, denn sie melden sich mit dem Token selbst beim Backend an,</li><li>leitet ohne gültige Anmeldung auf <code>/login?redirectTo=…</code> weiter und löscht dabei die Cookies,</li><li>leitet <code>/</code>, <code>/login</code> und Seiten, die die Routenrechte nicht erlauben, auf die Startseite um.</li></ol><p>Das Ergebnis von Schritt 1 hält jeder Prozess des Frontends 30 Sekunden je Zugangstoken vor. Mehrere Aufrufe kurz hintereinander, wie sie eine Seite mit vielen Remote Functions auslöst, kosten das Backend deshalb nur die erste Abfrage. Eine geänderte Rolle wirkt im Frontend dadurch bis zu 30 Sekunden später, zusätzlich zum Zwischenspeicher des Backends, siehe Abschnitt <a href="./32-rest-api.html#_32-3-berechtigungsprufung-in-der-schnittstelle">Berechtigungsprüfung in der Schnittstelle</a>.</p><p><strong>Erneuerung ohne Seitenwechsel.</strong> Der Zugangstoken gilt 15 Minuten. Bleibt jemand länger auf einer Seite, liefe er ab, ohne dass ein Hook zum Zug käme. Solange jemand angemeldet ist, erneuert <code>src/lib/utils/sessionKeepAlive.ts</code> ihn deshalb im Hintergrund über die Remote Function <code>refreshSession</code> (<code>src/lib/remote/auth/session.remote.ts</code>), nach der Hälfte der Gültigkeit, die das Backend meldet, also etwa alle siebeneinhalb Minuten. Die Seite lädt dabei nichts neu. Weil Browser die Zeitgeber von Tabs im Hintergrund drosseln, erneuert die Seite den Token außerdem, sobald ein Tab nach längerer Zeit wieder sichtbar wird.</p><p>Antwortet das Backend trotzdem mit 401, erneuern Kacheln, WMS-Anfragen und die Schaltfläche „Erneut versuchen“ in <code>QueryBoundary.svelte</code> die Anmeldung über <code>ensureFreshSession()</code> und wiederholen die Anfrage. Gleichzeitige Anfragen teilen sich eine Erneuerung, und innerhalb von 30 Sekunden nach einer erfolgreichen gilt die Anmeldung als frisch. Scheitert die Erneuerung, ist die Sitzung abgelaufen: Die Oberfläche meldet das und führt auf die Anmeldung, mit der aktuellen Adresse als <code>redirectTo</code>. Nach der Anmeldung öffnet sich dieselbe Ansicht mit demselben Objekt; den Kartenausschnitt stellt der gespeicherte Ausschnitt des Projekts wieder her.</p><p><strong>Routenschutz.</strong> Geprüft wird nicht der Pfad, sondern ein <strong>Rechteschlüssel</strong>: die Route-ID ohne den Präfix des Projekts und ohne Parameter, gebildet von <code>permissionKeyFor()</code> in <code>src/lib/config/routes.ts</code>. <code>/project/2/valuation</code> hat den Schlüssel <code>/valuation</code>, <code>/project/2/address/&lt;uuid&gt;/unit/&lt;uuid&gt;</code> den Schlüssel <code>/address/unit</code>. <code>canAccessRoute()</code> in <code>src/lib/utils/permissions.ts</code> prüft ihn gegen die Routenrechte aus <code>auth/permissions/</code>: Ein Muster, das genau dem Schlüssel entspricht, entscheidet; sonst das genaueste Muster, das ihn abdeckt, wobei <code>/address/*</code> und <code>/address</code> gleichermaßen alles unterhalb von <code>/address/</code> abdecken. Bei gleich genauen Mustern gewinnt die Erlaubnis. Was kein Muster erfasst, ist erlaubt. Server-Hook, Startseite und Navigationsleiste nutzen dieselbe Funktion. <code>permissions.ts</code> enthält außerdem <code>canView</code>, <code>canEdit</code> und <code>canDelete</code>, mit denen die Ansichten Schaltflächen nach den Modellrechten ein- und ausblenden.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Schlagen die Rechte beim Backend fehl, etwa weil <code>auth/permissions/</code> kurz nicht antwortet, erlaubt <code>canAccessRoute()</code> jede Seite, damit ein Aussetzer des Backends nicht alle aussperrt. Die Daten bleiben trotzdem geschützt, weil das Backend die Modellrechte bei jeder Anfrage selbst prüft. Ein Konto ohne Gruppe bekommt dagegen ausdrücklich keine Seite (<code>/*</code> verboten) und landet auf <code>/no-access</code>.</p></div><p>Routenrechte prüft nur das Frontend; was eine Anfrage an die Schnittstelle darf, entscheidet das Backend, siehe Abschnitt <a href="./32-rest-api.html#_32-3-berechtigungsprufung-in-der-schnittstelle">Berechtigungsprüfung in der Schnittstelle</a>. Wie eine neue Route mit Menüpunkt und Recht entsteht, beschreibt Abschnitt <a href="./36-erweitern-und-mitwirken.html#_36-2-eine-neue-route-samt-berechtigung-erganzen">Eine neue Route samt Berechtigung ergänzen</a>.</p>',67)])])}const m=n(i,[["render",o]]);export{g as __pageData,m as default};
